//adds a toe lift controller to the valve biped
//hardcoded to existing names
function AddToeLift()
{
	//first let's see if ValveBiped is in the scene 
	//if it is this thing should work just fine, if it's not exit the script
	var checkExist = ActiveSceneRoot.FindChild("ValveBiped");
	if(!checkExist)
	{
		logmessage ("No Biped Found");
		return;
	} 
	ltoe = ("LeftToeLift");
	rtoe = ("RightToeLift");
	
	lnull = ("LToePivot");
	rnull = ("RToePivot");
	MakeNulls(lnull,rnull);
	MoveNulls(lnull,rnull);
	MakeControls(ltoe, rtoe);
	MoveControls(ltoe,rtoe);
	ReParentFoot(lnull,rnull,ltoe,rtoe);
	FixTwist();
	AddToGroups(lnull,rnull,ltoe,rtoe);
}


//make the nulls
function MakeNulls(leftnull,rightnull)
{
	nulls = new Array(leftnull, rightnull);
	for (i in nulls)
	{
		GetPrim ("Null", nulls[i], null, null);
	}
}

//put the nulls in the right place
function MoveNulls(leftnull, rightnull)
{
	toe = ("ValveBiped.LBall");
	toe1 = ("ValveBiped.RBall");
	MatchTransform (leftnull, toe, siSRT, null);
	MatchTransform (rightnull, toe1, siSRT, null);
	SetNeutralPose(leftnull, siSRT, false);
	SetNeutralPose(rightnull, siSRT, false);
	//hide them
	vis = (".visibility.viewvis");
	leftvis = (leftnull + vis);
	rightvis = (rightnull + vis);
	setvis = new Array (leftvis, rightvis);
	for (i in setvis)
	{
		SetValue (setvis[i], 0, null)
	}
}
//make the control boxes
function MakeControls(lefttoe, righttoe)
{

	boxes = new Array(lefttoe, righttoe);
	for (i in boxes)
	{
		cube = GetPrim("Cube", boxes[i], null, null);

		length = (cube + ".cube.length");
		SetValue(length, 2, null);
		//set the display color
		display = (cube +".display");
		MakeLocal(display, siDefaultPropagation);
		displaytypes = new Array(".staticsel",".intsel",".playbacksel",".staticunselnear",".intunselnear",".playbackunselnear",".staticunselfar",".intunselfar",".playbackunselfar");
		for (x in displaytypes)
		{
			setdisplay = (display + displaytypes[x]);
			logmessage (setdisplay);
			SetValue(setdisplay, 0, null);
		}
	}
	lcolor = (lefttoe + ".display.wirecol");
	rcolor = (righttoe + ".display.wirecol");
	SetValue(lcolor,94,null);
	SetValue(rcolor, 26,null);
}

//put them in the right place
function MoveControls(lefttoe, righttoe)
{
	toe = ("ValveBiped.LToe");
	toe1 = ("ValveBiped.RToe");
	logmessage ("putting " + lefttoe + " " + righttoe + " in the right place");
	MatchTransform (lefttoe, toe, siSRT, null);
	MatchTransform (righttoe, toe1, siSRT, null);
	SetNeutralPose(lefttoe, siSRT, false);
	SetNeutralPose(righttoe, siSRT, false);
}

//make the new toe lift drive the foot
function ReParentFoot(leftnull,rightnull,lefttoe,righttoe)
{
	ParentObj("ValveBiped.LAnkleGroup", leftnull);
	DeselectAll();
	ParentObj("ValveBiped.RAnkleGroup", rightnull);
	DeselectAll();
	newlnull = ("ValveBiped." + leftnull);
	newrnull = ("ValveBiped." + rightnull);
	ParentObj(newlnull, "ValveBiped.LHeel");
	DeselectAll();
	ParentObj(newrnull,"ValveBiped.RHeel");
	DeselectAll();
	ParentObj("ValveBiped.LeftFoot", lefttoe);
	DeselectAll();
	ParentObj("ValveBiped.RightFoot", righttoe);
	DeselectAll();
	newltoe = ("ValveBiped." + lefttoe);
	newrtoe = ("ValveBiped." + righttoe);
	logmessage (newlnull + newrnull + newltoe + newrtoe);
	ApplyCns("Orientation", newlnull, newltoe, null);
	ApplyCns("Orientation", newrnull, newrtoe, null);
}

//fix the foot bone twist limits
function FixTwist()
{
	bones = new Array("ValveBiped.Bip01_L_Foot", "ValveBiped.Bip01_R_Foot");
	for (i in bones)
	{
		active = (".joint.rotlim_active");
		limitactive = (bones[i] + active);
		SetValue (limitactive, true, null);
		minx = (".joint.rotminx");
		setmin = (bones[i]+minx);
		SetValue (setmin, 0, null);
		maxx = (".joint.rotmaxx");
		setmax = (bones[i]+ maxx);
		SetValue (setmax, 0, null);
	}
}
	
//add everything to the right groups
function AddToGroups (leftnull,rightnull,lefttoe,righttoe)
{
	VB = ("ValveBiped.");
	AAC = (VB + "All_Animateable_Controls");
	RC = (VB + "Rotation_Controls");

	leftcontrol = (VB + lefttoe);
	rightcontrol = (VB + righttoe);
	controls = new Array (leftcontrol, rightcontrol);
	var AACExist = Dictionary.GetObject(AAC, false);
	var RCExist = Dictionary.GetObject(RC, false);
	for (i in controls)
	{
		if (AACExist)
		{
			SIAddToGroup(AAC, controls[i],null);
		}
		if (RCExist)
		{
			SIAddToGroup(RC, controls[i],null);
		}
	}
	LLC = (VB + "Left_Leg_Controls");
	RLC = (VB + "Right_Leg_Controls");
	var LLCExist = Dictionary.GetObject(LLC, false);
	var RLCExist = Dictionary.GetObject(RLC,false);
	if (LLCExist)
	{
		SIAddToGroup (LLC, leftcontrol);
	}
	if (RLCExist)
	{
		SIAddToGroup (RLC, rightcontrol);
	}
	
	// quick way to get john morello's request in
	// need to remove hardcoded names at some point
	CopyPaste("ValveBiped.LeftToeLift", null, "ValveBiped.Plotted", 1);
	CopyPaste("ValveBiped.RightToeLift", null, "ValveBiped.Plotted", 1);

	SelectObj("ValveBiped.RightToeLift");
	SetMarking("kine.local.ori.euler.rotx");
	AddToMarking("kine.local.ori.euler.roty");
	AddToMarking("kine.local.ori.euler.rotz");
	CreateMarkingSet("ValveBiped.RightToeLift");
	AddProp("Transform Setup", "", "", "", null);
	SetValue("ValveBiped.RightToeLift.transformsetup.tool", 3, null);

	SelectObj("ValveBiped.LeftToeLift");
	SetMarking("kine.local.ori.euler.rotx");
	AddToMarking("kine.local.ori.euler.roty");
	AddToMarking("kine.local.ori.euler.rotz");
	CreateMarkingSet("ValveBiped.LeftToeLift");
	AddProp("Transform Setup", "", "", "", null);
	SetValue("ValveBiped.LeftToeLift.transformsetup.tool", 3, null);
}
